
.camera-capture {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
}

.camera-capture__prompt,
.camera-capture__status {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
  padding: 2rem 1rem;
  color: var(--farm-text-muted);
}

.camera-capture__status--error {
  color: var(--farm-wood-dark);
}

.camera-capture__spinner {
  width: 1.75rem;
  height: 1.75rem;
  animation: camera-capture-spin 1s linear infinite;
}

@keyframes camera-capture-spin {
  to {
    transform: rotate(360deg);
  }
}

.camera-capture__viewport {
  position: relative;
  width: 100%;
  max-width: 420px;
  aspect-ratio: 3 / 4;
  border-radius: 1rem;
  overflow: hidden;
  background: #000;
  border: 3px solid var(--farm-wood);
}

.camera-capture__video {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.camera-capture__shutter {
  position: absolute;
  left: 50%;
  bottom: 0.9rem;
  transform: translateX(-50%);
  width: 3.6rem;
  height: 3.6rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.25);
  border: 3px solid var(--farm-cream);
  display: flex;
  align-items: center;
  justify-content: center;
}

.camera-capture__shutter-inner {
  width: 2.7rem;
  height: 2.7rem;
  border-radius: 999px;
  background: var(--farm-cream);
}

.camera-capture__canvas-hidden {
  display: none;
}
